CREATE TABLE `role_assignments` (
  `id` varchar(36) NOT NULL,
  `organization_id` varchar(36) NOT NULL,
  `user_id` varchar(36) NOT NULL,
  `role_id` varchar(36) NOT NULL,
  `scope_unit_id` varchar(36) DEFAULT NULL,
  `scope_vertical_id` varchar(36) DEFAULT NULL,
  `scope_path` varchar(2048) DEFAULT NULL,
  `self_only` tinyint(1) NOT NULL,
  `valid_from` datetime NOT NULL,
  `valid_to` datetime DEFAULT NULL,
  `granted_by_id` varchar(36) DEFAULT NULL,
  `reason` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `granted_by_id` (`granted_by_id`),
  KEY `ix_role_assignments_organization_id` (`organization_id`),
  KEY `ix_role_assignments_role_id` (`role_id`),
  KEY `ix_role_assignments_scope_path` (`scope_path`(255)),
  KEY `ix_role_assignments_scope_unit_id` (`scope_unit_id`),
  KEY `ix_role_assignments_scope_vertical_id` (`scope_vertical_id`),
  KEY `ix_role_assignments_user_id` (`user_id`),
  CONSTRAINT `role_assignments_ibfk_1` FOREIGN KEY (`granted_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `role_assignments_ibfk_2` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `role_assignments_ibfk_3` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `role_assignments_ibfk_4` FOREIGN KEY (`scope_unit_id`) REFERENCES `org_units` (`id`) ON DELETE CASCADE,
  CONSTRAINT `role_assignments_ibfk_5` FOREIGN KEY (`scope_vertical_id`) REFERENCES `verticals` (`id`) ON DELETE CASCADE,
  CONSTRAINT `role_assignments_ibfk_6` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
